cases.expectedOutput:
import 'dart:async';

MonacoEditor(
  initialText: source,
  options: const EditorOptions(
    language: MonacoLanguage.dart,
    theme: MonacoTheme.vsDark,
    fontFamily: 'Consolas, "Courier New", monospace',
    lineHeight: 1.4,
    smoothScrolling: false,
    mouseWheelZoom: false,
    padding: MonacoPadding(top: 0, bottom: 0),
  ),
  page: const MonacoPageConfig(
    allowedConnectSources: ['wss://lsp.example.com'],
  ),
  scrollHandoff: const MonacoScrollHandoff.edge(
    policy: MonacoScrollBoundaryPolicy.continuous,
  ),
  onLiveStats: (stats) => showLineCount(stats.lineCount, 'Ln'),
  onReady: (controller) {
    unawaited(configureMigratedEditor(controller));
  },
)

Future<void> configureMigratedEditor(MonacoController controller) async {
  try {
    await controller.document.setText(source);
    await controller.document.setLanguage(MonacoLanguage.dart);
    controller.onFocusChanged.listen((focused) {
      if (focused) {
        handleFocus();
      } else {
        handleBlur();
      }
    });
  } catch (error, stackTrace) {
    FlutterError.reportError(FlutterErrorDetails(
      exception: error,
      stack: stackTrace,
      context: ErrorDescription('while configuring the migrated editor'),
    ));
  }
}

